{
  "name": "xstate-inspect-cli",
  "version": "0.0.4",
  "author": "Matt Pocock",
  "license": "MIT",
  "bin": "src/index.js",
  "dependencies": {
    "xstate-inspect-no-fast-stringify": "0.0.1",
    "vite": "^2.1.4",
    "ws": "^7.4.4",
    "xstate": "^4.17.1"
  },
  "scripts": {
    "dev": "TS_NODE_COMPILER_OPTIONS='{\"module\":\"commonjs\"}' ts-node-dev --transpile-only --no-notify src/index.ts",
    "local-link": "yarn unlink && npm run chmod:index && yarn link",
    "chmod:index": "chmod +x src/index.js"
  },
  "devDependencies": {
    "@types/node": "^14.14.37",
    "ts-node-dev": "^1.1.6",
    "typescript": "^4.2.3"
  }
}

import { inspect } from "xstate-inspect-no-fast-stringify";
import { interpret } from "xstate";

inspect({
  iframe: () => document.getElementById("xstate-iframe") as any,
});

(async () => {
  const exports = await import(
    /* @vite-ignore */
    // @ts-ignore
    FILE_PATH
  );

  const machines = Object.values(exports);

  let foundMachine = false;

  machines.forEach((machine) => {
    // @ts-ignore
    if (machine && machine.__xstatenode) {
      // @ts-ignore
      interpret(machine, {
        devTools: true,
      }).start();

      foundMachine = true;
    }
  });

  if (!foundMachine) {
    alert("No machines found exported from this file!");
  }
})();

#!/usr/bin/env node

const { createServer } = require("vite");
const path = require("path");

const [, , filePath] = process.argv;

if (!filePath) {
  console.log("You must provide a file path");
  process.exit(1);
}

const absoluteFilePath = path.resolve(process.cwd(), filePath);

(async () => {
  const server = await createServer({
    configFile: false,
    server: {
      port: 3001,
      open: true,
    },
    plugins: [
      {
        name: "Index Html Creator",
        apply: "serve",
        configureServer: (server) => {
          server.app.use((req, res, next) => {
            if (req.url === "/") {
              res.write(`
                <html>
                  <head>
                    <style>
                      body {
                        margin: 0px;
                        height: 100vh;
                        width: 100vw;
                        display: flex;
                        align-items: stretch;
                      }

                      body iframe {
                        width: 100%;
                        border: 0px solid;
                      }
                    </style>
                    <title>XState Inspector</title>
                  </head>
                  <body>
                  <iframe id="xstate-iframe"></iframe>
                  <script>
                    const FILE_PATH = "${absoluteFilePath}";
                  </script>
                  <script type="module" src="${path.resolve(
                    __dirname,
                    "./initInspector.ts",
                  )}"></script>

                  </body>
                </html>
              `);
              res.end();
            } else {
              next();
            }
          });
        },
      },
    ],
  });

  await server.listen();
})();
